mapper.select:
SELECT uuid, external_id
FROM evaluation_rubrics
WHERE organization_uuid = #{organizationUUID}
AND workspace_uuid = #{workspaceUUID}
AND external_id = #{externalID}
AND deleted_at IS NULL
FOR UPDATE

SELECT v.uuid, v.external_id, v.organization_uuid, v.workspace_uuid, v.rubric_uuid, v.version, v.body, v.pass_score, v.model, v.created_at
FROM evaluation_rubric_versions v
JOIN evaluation_rubrics r ON r.uuid = v.rubric_uuid
WHERE r.organization_uuid = #{organizationUUID}
AND r.workspace_uuid = #{workspaceUUID}
AND r.external_id = #{externalID}
AND r.deleted_at IS NULL
ORDER BY v.version DESC

SELECT 
FROM evaluation_rubrics r
JOIN evaluation_rubric_versions v ON v.rubric_uuid = r.uuid
WHERE r.organization_uuid = #{organizationUUID}
AND r.workspace_uuid = #{workspaceUUID}
AND r.external_id = #{externalID}
AND r.deleted_at IS NULL
AND v.version = (
    SELECT MAX(version) FROM evaluation_rubric_versions WHERE rubric_uuid = r.uuid
)

SELECT 
FROM evaluation_rubrics r
JOIN evaluation_rubric_versions v ON v.rubric_uuid = r.uuid
WHERE r.organization_uuid = #{params.OrganizationUUID}
AND r.workspace_uuid = #{params.WorkspaceUUID}
AND r.deleted_at IS NULL
AND v.version = (
    SELECT MAX(version) FROM evaluation_rubric_versions WHERE rubric_uuid = r.uuid
)
ORDER BY r.created_at DESC, r.uuid DESC
LIMIT #{params.Limit} OFFSET #{params.Offset}

mapper.update:
UPDATE evaluation_rubrics
SET updated_at = #{updatedAt}
WHERE uuid = #{rubricUUID}
AND deleted_at IS NULL

UPDATE evaluation_rubrics
SET deleted_at = #{deletedAt}, updated_at = #{deletedAt}
WHERE organization_uuid = #{organizationUUID}
AND workspace_uuid = #{workspaceUUID}
AND external_id = #{externalID}
AND deleted_at IS NULL
